async function e(a,t){const n=await fetch(a,{headers:{"Content-Type":"application/json"},...t}),r=await n.json();if(!n.ok)throw new Error(r.message||"Permintaan pesanan gagal");return r}async function o(a){return(await e("/api/v1/orders",{method:"POST",body:JSON.stringify(a)})).order}async function s(){return(await e("/api/v1/orders")).orders}async function d(a){return(await e(`/api/v1/orders?nota=${encodeURIComponent(a)}`)).order}async function c(a,t){return(await e(`/api/v1/orders/${encodeURIComponent(a)}/payment`,{method:"PATCH",body:JSON.stringify({bayar:t})})).order}export{s as a,c as b,o as c,d as f};
